CREATE FUNCTION public.preview_patient_communication_context() RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('snapshot',public.patient_request_snapshot(r.id),'timezone',t.communication_timezone,'activeRelationship',CASE WHEN r.workspace_id=coalesce(r.patient_workspace_id,r.workspace_id) AND r.requester_user_id=auth.uid() THEN true ELSE EXISTS(SELECT 1 FROM public.account_business_connections c WHERE c.active AND ((c.workspace_a=r.workspace_id AND c.workspace_b=r.patient_workspace_id) OR (c.workspace_b=r.workspace_id AND c.workspace_a=r.patient_workspace_id))) END,'version',md5(concat_ws('|',t.updated_at::text,t.status,t.pickup_date::text,t.pickup_time::text,t.communication_timezone,r.lifecycle_state,r.last_updated_at::text))) FROM public.ride_requests r LEFT JOIN LATERAL (SELECT * FROM public.trips WHERE ride_request_id=r.id ORDER BY created_at DESC LIMIT 1) t ON true WHERE public.patient_request_access(r.id) ORDER BY r.created_at DESC LIMIT 100 $$;
REVOKE ALL ON FUNCTION public.preview_patient_communication_context() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.preview_patient_communication_context() TO authenticated;
CREATE FUNCTION public.cancel_communication_preparation(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n public.notifications;ws uuid; BEGIN
 SELECT * INTO n FROM public.notifications WHERE id=_id AND communication IS NOT NULL FOR UPDATE; ws:=(n.communication->>'workspaceId')::uuid;
 IF n.id IS NULL OR NOT public.admin_can('messaging','manage') OR NOT public.admin_can_account(ws) OR n.communication->>'state' NOT IN ('prepared','suppressed','not_configured','failed') OR (n.communication->>'scheduledAt')::timestamptz<=now() THEN RAISE EXCEPTION 'Future unsent notice unavailable'; END IF;
 INSERT INTO public.notifications(user_id,type,title,body,ride_request_id,communication) VALUES(n.user_id,'communication_cancellation','Notice canceled',NULL,n.ride_request_id,n.communication||jsonb_build_object('reference','MFN-C-'||upper(replace(gen_random_uuid()::text,'-','')),'state','canceled','reason','authorized_admin_cancellation','dedupeKey',n.communication->>'dedupeKey'||':canceled','canceledAt',now(),'actorId',auth.uid(),'supersedesId',n.id)) ON CONFLICT DO NOTHING;
 INSERT INTO public.account_security_audit(user_id,sender_mfn_id,workspace_id,workspace_mfn_id,event_type,result) SELECT auth.uid(),p.mfn_id,ws,w.mfn_id,'communication_preparation_canceled','canceled' FROM public.user_profiles p,public.workspaces w WHERE p.user_id=auth.uid() AND w.id=ws; END $$;
REVOKE ALL ON FUNCTION public.cancel_communication_preparation(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cancel_communication_preparation(uuid) TO authenticated;
